SET CLIENT_ENCODING TO UTF8;
SET STANDARD_CONFORMING_STRINGS TO ON;
BEGIN;
CREATE TABLE "temp_uc_est" ("gid" serial,
"id" numeric,
"nome_uc" varchar(254),
"categoria" varchar(254),
"grupo" varchar(254),
"ato_legal" varchar(254),
"area_ofic" numeric,
"area_geo" numeric,
"municipios" varchar(254),
"bioma" varchar(254),
"esfera" varchar(254),
"reg_ief" varchar(254),
"id_uc" varchar(254),
"v_atual" varchar(254),
"geom" geometry(MULTIPOLYGON,4674));
ALTER TABLE "temp_uc_est" ADD PRIMARY KEY ("gid");
CREATE INDEX ON "temp_uc_est" USING GIST ("geom");
COMMIT;
ANALYZE "temp_uc_est";
